// Map employee_id -> mock data file name
const id = $json.body?.employee_id || $json.employee_id;
const files = {
  emp_001: 'emp_001_priya_sharma.json',
  emp_002: 'emp_002_arjun_mehta.json',
  emp_003: 'emp_003_kavya_nair.json'
};
if (!files[id]) throw new Error(`Unknown employee_id: ${id}`);
// TODO: replace <GITHUB_USER>/<REPO>/<BRANCH> with your repo
return [{ json: { employee_id: id, url: `https://raw.githubusercontent.com/<GITHUB_USER>/<REPO>/main/data/mock_employees/${files[id]}` } }];

// Parse + validate synthesis output
let text = $json.output?.message?.content?.[0]?.text ?? $json.content?.[0]?.text ?? $json.choices?.[0]?.message?.content;
if (!text) throw new Error('No LLM text in response');
text = text.trim().replace(/^```(json)?/,'').replace(/```$/,'').trim();
const synthesis = JSON.parse(text);
for (const f of ['strengths','growth_areas','impact_highlights','goal_progress']) {
  if (!Array.isArray(synthesis[f])) throw new Error(`Synthesis missing field: ${f}`);
}
const employee = $('Build Synthesis Prompt').first().json.employee;
return [{ json: { synthesis, employee } }];

let text = $json.output?.message?.content?.[0]?.text ?? $json.content?.[0]?.text ?? $json.choices?.[0]?.message?.content;
if (!text) throw new Error('No LLM text in bias response');
text = text.trim().replace(/^```(json)?/,'').replace(/```$/,'').trim();
const audited = JSON.parse(text);
const { employee } = $('Build Bias Prompt').first().json;

// Count flags by type for the summary
const sections = ['strengths','growth_areas','impact_highlights','goal_progress'];
const counts = {};
for (const s of sections) {
  for (const p of (audited[s] || [])) {
    if (p.flag) counts[p.flag.type] = (counts[p.flag.type] || 0) + 1;
  }
}
const report = {
  employee_id: employee.employee_id,
  employee_name: employee.name,
  ...Object.fromEntries(sections.map(s => [s, audited[s] || []])),
  overall_bias_summary: audited.overall_bias_summary || (Object.keys(counts).length ? `Flags detected: ${JSON.stringify(counts)}` : 'No bias flags detected.'),
  flag_counts: counts,
  status: 'pending_approval'
};
return [{ json: { report, draft_json: JSON.stringify(report), employee_id: employee.employee_id } }];
